const g = await tools.get_goal({});
if (g.goal && g.goal.phase === "active") {
  const res = await tools.update_goal({ goal_id: g.goal.id, revision: g.goal.revision, action: "complete" });
  return { marked: true, phase: res.goal ? res.goal.phase : "?" };
}
return { marked: false, phase: g.goal ? g.goal.phase : "none" };
